@namespace sv_7b5211144c504da19c37927f1e58a9c3.Components.Pages.Settings

<nav class="settings-sidebar" aria-label="Settings navigation">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item">
                <button class="settings-nav-link @(ActiveSection == section.Key ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section.Key)"
                        aria-current="@(ActiveSection == section.Key ? "page" : null)">
                    <span class="settings-nav-icon">@section.Icon</span>
                    <span>@section.Label</span>
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private record NavItem(string Key, string Label, string Icon);

    private static readonly NavItem[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨"),
    ];
}

.settings-sidebar {
    width: 220px;
    min-height: 100%;
    border-right: 1px solid #dee2e6;
    background: #f8f9fa;
    padding: 1rem 0;
}

.settings-nav {
    list-style: none;
    margin: 0;
    padding: 0;
}

.settings-nav-item {
    margin: 0;
}

.settings-nav-link {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    width: 100%;
    padding: 0.75rem 1.25rem;
    border: none;
    background: none;
    color: #495057;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    text-align: left;
}

.settings-nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-nav-link.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.settings-nav-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

