@namespace sv_7b5211144c504da19c37927f1e58a9c3.Components.Pages.Settings
@using sv_7b5211144c504da19c37927f1e58a9c3.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    <h3>Notification Preferences</h3>

    @if (_loading)
    {
        <p>Loading preferences…</p>
    }
    else
    {
        <div class="toggle-group">
            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_emailNotifications" />
                    <span class="form-check-label">Email Notifications</span>
                </label>
                <span class="text-muted small">Receive notifications via email</span>
            </div>

            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_pushNotifications" />
                    <span class="form-check-label">Push Notifications</span>
                </label>
                <span class="text-muted small">Receive browser push notifications</span>
            </div>

            <div class="toggle-item">
                <label class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" @bind="_weeklyDigest" />
                    <span class="form-check-label">Weekly Digest</span>
                </label>
                <span class="text-muted small">Get a weekly summary of activity</span>
            </div>
        </div>

        <hr />

        <h5>Muted Channels</h5>
        <p class="text-muted small">Uncheck channels you want to mute.</p>

        @if (_channels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            <div class="channel-list">
                @foreach (var channel in _channels)
                {
                    <label class="form-check channel-check">
                        <input class="form-check-input" type="checkbox"
                               checked="@(!_mutedChannels.Contains(channel))"
                               @onchange="e => ToggleMute(channel, e)" />
                        <span class="form-check-label">@channel</span>
                    </label>
                }
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Preferences")
        </button>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3" role="alert">@_successMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private List<string> _channels = new();

    protected override async Task OnInitializedAsync()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);

        // Build the full channel list from muted channels so we have something to display.
        // In a real app this would come from a separate channel service.
        _channels = prefs.MutedChannels.Count > 0
            ? prefs.MutedChannels.ToList()
            : new List<string> { "general", "announcements", "random", "engineering", "design" };

        _loading = false;
    }

    private void ToggleMute(string channel, ChangeEventArgs e)
    {
        var isEnabled = (bool)(e.Value ?? false);
        if (isEnabled)
            _mutedChannels.Remove(channel);
        else
            _mutedChannels.Add(channel);
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var prefs = new NotificationPrefs(
            _emailNotifications,
            _pushNotifications,
            _weeklyDigest,
            _mutedChannels.ToList());

        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _successMessage = "Notification preferences saved!";
    }
}

