@namespace sv_7b5211144c504da19c37927f1e58a9c3.Components.Pages.Settings
@using sv_7b5211144c504da19c37927f1e58a9c3.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    <h3>Appearance Settings</h3>

    @if (_loading)
    {
        <p>Loading appearance settings…</p>
    }
    else
    {
        <!-- Theme -->
        <fieldset class="mb-4">
            <legend class="h6">Theme</legend>
            <div class="d-flex gap-3">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span class="form-check-label">@theme</span>
                    </label>
                }
            </div>
        </fieldset>

        <!-- Font Size -->
        <fieldset class="mb-4">
            <legend class="h6">Font Size</legend>
            <div class="d-flex gap-3">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span class="form-check-label">@size</span>
                    </label>
                }
            </div>
        </fieldset>

        <!-- Language -->
        <div class="form-group mb-4">
            <label class="form-label h6" for="language">Language</label>
            <select id="language" class="form-select" style="max-width: 250px;" @bind="_language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <label class="form-check form-switch">
                <input class="form-check-input" type="checkbox" @bind="_compactMode" />
                <span class="form-check-label">Compact Mode</span>
            </label>
            <span class="text-muted small d-block mt-1">Reduce spacing and padding throughout the UI</span>
        </div>

        <!-- Live Preview -->
        <div class="preview-area mb-4">
            <h6>Preview</h6>
            <div class="preview-box @GetPreviewThemeClass()" style="@GetPreviewFontStyle()">
                <div class="preview-header">
                    <strong>Sample Card</strong>
                </div>
                <div class="preview-body" style="@(_compactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                    <p style="margin-bottom: @(_compactMode ? "0.25rem" : "0.75rem");">
                        This is how your content will look with the current settings.
                    </p>
                    <p class="text-muted" style="margin-bottom: 0;">
                        Theme: @_theme · Font: @_fontSize · Language: @GetLanguageName() · Compact: @(_compactMode ? "On" : "Off")
                    </p>
                </div>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>

        @if (_successMessage is not null)
        {
            <div class="alert alert-success mt-3" role="alert">@_successMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;

        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        _saving = false;
        _successMessage = "Appearance settings saved!";
    }

    private string GetPreviewThemeClass() => _theme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string GetPreviewFontStyle() => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private string GetLanguageName() => _language switch
    {
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => "English"
    };
}

.appearance-section {
    max-width: 600px;
}

.preview-area {
    margin-top: 1rem;
}

.preview-box {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f8f9fa;
}

.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-header {
    background: #2d2d2d;
    border-color: #444;
}

.preview-dark .text-muted {
    color: #adb5bd !important;
}

.preview-system {
    background: #f5f5f5;
    color: #333;
}

.preview-system .preview-header {
    background: #e8e8e8;
}

